import { Item, ItemContent, ItemMedia, ItemTitle } from "@/registry/erbium/ui/item";
import { Spinner } from "@/registry/erbium/ui/spinner";

export default function SpinnerDemo() {
  return (
    <div className="flex w-full max-w-xs flex-col gap-4 [--radius:1rem]">
      <Item variant="card">
        <ItemMedia>
          <Spinner />
        </ItemMedia>
        <ItemContent>
          <ItemTitle className="line-clamp-1">Processing payment...</ItemTitle>
        </ItemContent>
        <ItemContent className="flex-none justify-end">
          <span className="text-caption tabular-nums">$100.00</span>
        </ItemContent>
      </Item>
    </div>
  );
}

import Demo from "../examples/spinner-demo";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <Demo />
  </div>
);

export default Example;
